import { addDays } from "./billing"
import { ClientStatus, LeadSource, type Client, type ClientContact } from "../../types/workforce"

/** One person at a client, as listed on the Contacts page (CRM step 6). */
export interface ContactRow {
  contact: ClientContact
  client: Client
}

/** Every contact of every client, main contacts first, then by name. */
export function allContacts(clients: Client[]): ContactRow[] {
  return clients
    .flatMap((client) => client.contacts.map((contact) => ({ contact, client })))
    .sort((a, b) => a.client.name.localeCompare(b.client.name) || Number(b.contact.isPrimary) - Number(a.contact.isPrimary) || a.contact.name.localeCompare(b.contact.name))
}

/** A contact's e-mails and phones, main ones first, without blanks or repeats. */
export const contactEmails = (c: ClientContact) => [...new Set([c.email, ...(c.otherEmails ?? [])].map((x) => x.trim()).filter(Boolean))]
export const contactPhones = (c: ClientContact) => [...new Set([c.phone ?? "", ...(c.otherPhones ?? [])].map((x) => x.trim()).filter(Boolean))]

/** A client dropped while still a lead: archived with a reason and never converted. */
export const isLostLead = (c: Client) => c.status === ClientStatus.ARCHIVED && !!c.lostReason && !c.convertedAt

export interface LeadStats {
  /** Leads still open */
  open: number
  /** Leads added in the last 30 days, open or not */
  newRecently: number
  /** Converted and dropped in the last 90 days */
  converted: number
  lost: number
  /** Share of the leads decided in the last 90 days that became clients; null when none was decided */
  conversionRate: number | null
  /** Open leads by where they came from, largest first */
  bySource: { source: LeadSource | "unknown"; count: number }[]
}

export function leadStats(clients: Client[], today: string): LeadStats {
  const since30 = addDays(today, -30)
  const since90 = addDays(today, -90)
  const open = clients.filter((c) => c.status === ClientStatus.LEAD)
  const everLead = clients.filter((c) => c.status === ClientStatus.LEAD || c.convertedAt || isLostLead(c))
  const converted = clients.filter((c) => c.convertedAt && c.convertedAt >= since90).length
  const lost = clients.filter((c) => isLostLead(c) && c.updatedAt.slice(0, 10) >= since90).length
  const counts = new Map<LeadSource | "unknown", number>()
  for (const c of open) counts.set(c.leadSource ?? "unknown", (counts.get(c.leadSource ?? "unknown") ?? 0) + 1)
  return {
    open: open.length,
    newRecently: everLead.filter((c) => c.createdAt.slice(0, 10) >= since30).length,
    converted,
    lost,
    conversionRate: converted + lost ? Math.round((converted / (converted + lost)) * 100) : null,
    bySource: [...counts].map(([source, count]) => ({ source, count })).sort((a, b) => b.count - a.count || String(a.source).localeCompare(String(b.source))),
  }
}
